-- Core tables (seat inventory is per journey date)
CREATE TABLE Station (
  id INT PRIMARY KEY, name VARCHAR(100), city VARCHAR(100)
);
CREATE TABLE Train (
  id INT PRIMARY KEY, name VARCHAR(100), type ENUM('Express','Local')
);
-- Ordered stops so intermediate cities are queryable
CREATE TABLE TrainStop (
  id INT PRIMARY KEY, train_id INT, station_id INT,
  stop_order INT, arrival TIME, departure TIME,
  UNIQUE(train_id, stop_order)
);
CREATE TABLE TrainRun (
  id INT PRIMARY KEY, train_id INT, journey_date DATE,
  UNIQUE(train_id, journey_date)
);
CREATE TABLE SeatInventory (
  id INT PRIMARY KEY,
  train_run_id INT,          -- ties seat to a specific date
  coach VARCHAR(8), seat_number INT,
  class ENUM('1A','2A','3A','SL'),
  status ENUM('AVAILABLE','BOOKED','LOCKED'),
  version INT DEFAULT 0,     -- optimistic locking
  UNIQUE(train_run_id, coach, seat_number)
);
CREATE TABLE Booking (
  id INT PRIMARY KEY, user_id INT, seat_inventory_id INT,
  pnr VARCHAR(12) UNIQUE,
  status ENUM('CONFIRMED','CANCELLED','WAITING'),
  idempotency_key VARCHAR(64) UNIQUE,
  created_at TIMESTAMP
);

-- Routes Delhi → Mumbai (any intermediate stop pair on same train)
SELECT t.name AS train, s1.city AS src, s2.city AS dst
FROM Train t
JOIN TrainStop ts1 ON ts1.train_id = t.id
JOIN TrainStop ts2 ON ts2.train_id = t.id AND ts2.stop_order > ts1.stop_order
JOIN Station s1 ON s1.id = ts1.station_id AND s1.city = 'Delhi'
JOIN Station s2 ON s2.id = ts2.station_id AND s2.city = 'Mumbai';

-- Available seats for a run
SELECT * FROM SeatInventory
WHERE train_run_id = ? AND status = 'AVAILABLE';

